INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Angebotseinholung immer eine öffentliche Ausschreibung?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch formlos erfolgen"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend öffentlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Angebotseinholung?', 3, '[{"text": "Beste Konditionen finden", "correct": true, "because": "Vergleicht Anbieter"}, {"text": "Projekt starten", "correct": false, "because": "Folgt später"}, {"text": "Kosten senken", "correct": false, "because": "Indirektes Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur Angebotseinholung?', 5, '[{"text": "Anforderungsbeschreibung", "correct": true, "because": "Definiert Bedarf"}, {"text": "Lieferantenauswahl", "correct": true, "because": "Bestimmt Anbieter"}, {"text": "Marketingstrategie", "correct": false, "because": "Kein Bestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Angebotseinholung erfordert klare Kriterien. b) Sie ist immer verbindlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht zwangsläufig verbindlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Angebotseinholung?', 4, '[{"text": "Anforderungen", "correct": false, "because": "Grundlage des Prozesses"}, {"text": "Vergleichskriterien", "correct": false, "because": "Entscheidend für Auswahl"}, {"text": "Firmenlogo", "correct": true, "because": "Irrelevant für Angebot"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Angebotseinholung mehrere Anbieter erfordert?', 2, '[{"text": "Nein", "correct": true, "because": "Ein Anbieter möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel gestaltbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für eine formlose Angebotseinholung?', 3, '[{"text": "Direkte Anfrage", "correct": true, "because": "Schnell und einfach"}, {"text": "Öffentliche Ausschreibung", "correct": false, "because": "Formaler Prozess"}, {"text": "Online-Befragung", "correct": false, "because": "Weniger üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zu einer effektiven Angebotseinholung?', 5, '[{"text": "Klare Spezifikationen", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Bewertungsmatrix", "correct": true, "because": "Erleichtert Vergleich"}, {"text": "Projektplanung", "correct": false, "because": "Folgt später"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Angebotseinholung dient dem Preisvergleich. b) Sie ist nur für Großprojekte nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für kleine Projekte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Angebotseinholung unwichtig?', 4, '[{"text": "Anbieterauswahl", "correct": false, "because": "Kern des Prozesses"}, {"text": "Angebotsfrist", "correct": false, "because": "Definiert Zeitrahmen"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss die Angebotseinholung dokumentiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Nicht zwingend, aber sinnvoll"}, {"text": "Ja", "correct": false, "because": "Abhängig vom Kontext"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt eine Angebotseinholung?', 4, '[{"text": "Wettbewerbsvergleich", "correct": true, "because": "Optimiert Auswahl"}, {"text": "Kostentransparenz", "correct": true, "because": "Klarheit über Preise"}, {"text": "Schnellere Lieferung", "correct": false, "because": "Nicht direkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Angebotseinholung immer zeitaufwendig ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann effizient sein"}, {"text": "Ja", "correct": false, "because": "Abhängig vom Umfang"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Angebotseinholung?', 3, '[{"text": "Klare Anforderungen", "correct": true, "because": "Basis für Vergleich"}, {"text": "Schnelligkeit", "correct": false, "because": "Qualität wichtiger"}, {"text": "Anbieteranzahl", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Angebotseinholung kann vertraulich sein. b) Sie führt immer zur Auftragsvergabe.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vergabe nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine schlecht geplante Angebotseinholung?', 5, '[{"text": "Unklare Angebote", "correct": true, "because": "Fehlende Spezifikation"}, {"text": "Zeitverlust", "correct": true, "because": "Nachfragen nötig"}, {"text": "Geringere Kosten", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Angebotseinholung unwichtig?', 3, '[{"text": "Bewertungskriterien", "correct": false, "because": "Entscheidend für Auswahl"}, {"text": "Angebotsfrist", "correct": false, "because": "Zeitliche Begrenzung"}, {"text": "Mitarbeiteranzahl", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann die Angebotseinholung abgelehnt werden?', 3, '[{"text": "Ja", "correct": true, "because": "Keine Verpflichtung zur Annahme"}, {"text": "Nein", "correct": false, "because": "Freiheit des Auftraggebers"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Angebotseinholung standardisiert sein muss?', 2, '[{"text": "Nein", "correct": true, "because": "Flexibel gestaltbar"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Angebotseinholung bei Projekten?', 4, '[{"text": "Lieferantenauswahl", "correct": true, "because": "Bestimmt Partner"}, {"text": "Projektstart", "correct": false, "because": "Folgt später"}, {"text": "Qualitätskontrolle", "correct": false, "because": "Andere Phase"}]');
